1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Assigns the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'} where
11	 * YY is the last two digits of the FISCAL YEAR of the {@code registrationDate} (the fiscal year
12	 * starts on 1 July, so a registration date on or after 1 July belongs to the next calendar year,
13	 * e.g. 'NSW-1A2B3C4D-M27' for a 2026-07-01 registration).
14	 *
15	 * <p>Runs after {@link AssignCustomerCode} (so the customer code exists) and {@link BuildOwner}
16	 * (so the registration date is set), and before {@link SaveOwner}, mutating the not-yet-persisted
17	 * owner in place.
18	 */
19	public class AssignMembershipNumber {
20	
21	    public void service(@Val Owner owner) {
22	        int yy = fiscalYearOf(owner.getRegistrationDate()) % 100;
23	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
24	    }
25	
26	    /**
27	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July, so
28	     * a date in July or later belongs to the next calendar year and an earlier date to the current
29	     * calendar year.
30	     */
31	    private static int fiscalYearOf(LocalDate date) {
32	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
33	    }
34	}
