1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} at creation.
11	 * Points start at 0 and accumulate: +2 when an email is present, +1 when the owner's
12	 * {@code namesakeCount} is 0, +2 for a household of 3 or more (its {@code householdSize}) and +3 for
13	 * tenure over one fiscal year (more than one elapsed fiscal year between the owner's
14	 * {@code registrationDate} and today, the fiscal year starting on 1 July). The points are
15	 * then mapped to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. Both fields are
16	 * stored on the owner.
17	 *
18	 * <p>Runs after {@link AssignHouseholdSize} and {@link AssignNamesakeCount} (so the household and
19	 * namesake snapshots exist) and before {@link SaveOwner}, mutating the not-yet-persisted owner in
20	 * place.
21	 */
22	public class AssignMembershipLevel {
23	
24	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
25	
26	    public void service(@Val Owner owner) {
27	        int points = 0;
28	
29	        String email = owner.getEmail();
30	        if (email != null && !email.isEmpty()) {
31	            points += 2;
32	        }
33	        Integer namesakeCount = owner.getNamesakeCount();
34	        if (namesakeCount != null && namesakeCount == 0) {
35	            points += 1;
36	        }
37	        Integer householdSize = owner.getHouseholdSize();
38	        if (householdSize != null && householdSize >= 3) {
39	            points += 2;
40	        }
41	        LocalDate registrationDate = owner.getRegistrationDate();
42	        if (registrationDate != null) {
43	            long elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
44	            if (elapsedFiscalYears > TENURE_FISCAL_YEARS_FOR_POINTS) {
45	                points += 3;
46	            }
47	        }
48	
49	        owner.setMembershipPoints(points);
50	        owner.setMembershipLevel(levelFor(points));
51	    }
52	
53	    /**
54	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July, so
55	     * a date in July or later belongs to the next calendar year and an earlier date to the current
56	     * calendar year.
57	     */
58	    private static int fiscalYearOf(LocalDate date) {
59	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
60	    }
61	
62	    private static int levelFor(int points) {
63	        if (points <= 1) {
64	            return 1;
65	        }
66	        if (points <= 3) {
67	            return 2;
68	        }
69	        if (points <= 5) {
70	            return 3;
71	        }
72	        return 4;
73	    }
74	}
