1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Caps the new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
9	 * {@code membershipLevel} among the other members of this owner's household — owners that already
10	 * share this owner's {@code householdId}. The ceiling is {@code max + 1}; when the derived level is
11	 * already at or below the ceiling it is left unchanged.
12	 *
13	 * <p>When the owner has no household ({@code householdId} is null) or no existing household member,
14	 * no ceiling applies and the level is left as {@link AssignMembershipLevel} derived it. Members whose
15	 * own {@code membershipLevel} is null (e.g. seed data) and soft-deleted owners are not counted.
16	 *
17	 * <p>Runs after {@link AssignMembershipLevel} (so the derived level exists) and before
18	 * {@link SaveOwner}, mutating the not-yet-persisted owner in place.
19	 */
20	public class CapMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String householdId = owner.getHouseholdId();
24	        if (householdId == null || householdId.isBlank()) {
25	            return; // no household -> no ceiling
26	        }
27	        Integer level = owner.getMembershipLevel();
28	        if (level == null) {
29	            return;
30	        }
31	
32	        Integer maxMemberLevel = null;
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
35	                continue; // never compare against self
36	            }
37	            if (Boolean.TRUE.equals(existing.getDeleted())) {
38	                continue;
39	            }
40	            if (!householdId.equals(existing.getHouseholdId())) {
41	                continue;
42	            }
43	            Integer existingLevel = existing.getMembershipLevel();
44	            if (existingLevel == null) {
45	                continue;
46	            }
47	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
48	                maxMemberLevel = existingLevel;
49	            }
50	        }
51	
52	        if (maxMemberLevel == null) {
53	            return; // no existing household member -> no ceiling
54	        }
55	        int ceiling = maxMemberLevel + 1;
56	        if (level > ceiling) {
57	            owner.setMembershipLevel(ceiling);
58	        }
59	    }
60	}
