1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	import tools.jackson.databind.ObjectMapper;
11	
12	/**
13	 * Emits an audit line to the dedicated {@code AUDIT} logger recording a successful owner
14	 * create. Runs after {@link SaveOwner} (so the owner id is assigned) and before the
15	 * responder. The line carries the owner id, the {@code customerCode}, the
16	 * {@code registrationDate}, the {@code membershipLevel} and the
17	 * {@code membershipNumber}.
18	 *
19	 * <p>Besides that human-readable line it emits an immutable structured {@link OwnerCreatedEvent}
20	 * as JSON to the same logger, with a {@code seq} that increases monotonically across creates.
21	 */
22	public class AuditOwnerCreated {
23	
24	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
25	
26	    private static final ObjectMapper MAPPER = new ObjectMapper();
27	
28	    /** Monotonically increasing sequence across all owner creates. */
29	    private static final AtomicLong SEQ = new AtomicLong();
30	
31	    public void service(@Val Owner owner) {
32	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
33	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
34	                owner.getMembershipLevel(), owner.getMembershipNumber());
35	
36	        // The owner's CURRENT primary identifier. Today that is the customerCode; when the
37	        // customerCode is later unified into the memberId, this one accessor changes and the
38	        // structured event automatically carries the memberId instead.
39	        String primaryIdentifier = owner.getCustomerCode();
40	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
41	                primaryIdentifier, owner.getMembershipLevel(), OwnerCreatedEvent.OWNER_CREATED);
42	        AUDIT.info("{}", MAPPER.writeValueAsString(event));
43	    }
44	}
