1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects creating an owner whose derived {@code identityKey} exactly matches an existing owner's.
10	 *
11	 * <p>The key — the hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
12	 * (see {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey()}) — is the one place
13	 * duplicate detection now lives, replacing the former separate telephone, email and household checks.
14	 * Because the telephone is part of the key, two people who share a surname and residence but have
15	 * different telephones have different keys: they are admitted as a soft match (flagged by
16	 * {@link AssignPossibleDuplicate}), not rejected here. Only an exact full-key match is a duplicate.
17	 *
18	 * <p>Runs after {@link NormalizeOwnerTelephone}/{@link NormalizeOwnerEmail} (so the key uses canonical
19	 * values) and before {@link SaveOwner} so a duplicate is a 409 (Conflict) rather than a persisted row.
20	 */
21	public class EnsureOwnerIdentityUnique {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = owner.getIdentityKey();
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
28	                continue;
29	            }
30	            if (Boolean.TRUE.equals(existing.getDeleted())) {
31	                continue; // a soft-deleted owner is treated as absent
32	            }
33	            if (identityKey.equals(existing.getIdentityKey())) {
34	                throw new DuplicateIdentityException(identityKey);
35	            }
36	        }
37	    }
38	}
