1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.Soundex;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Flags a soft (non-hard) duplicate. The new owner is created regardless, but when its
11	 * {@code identityKey} differs from an existing owner's yet they share a surname — the same
12	 * {@link Soundex} code for the last name — and the same postcode, it is recorded as a possible
13	 * duplicate of that owner.
14	 *
15	 * <p>A <em>declared</em> household member — a request that set {@code sharesHousehold} — is never a
16	 * suspected duplicate: it was accepted deliberately, so this step clears the flag and returns.
17	 *
18	 * <p>Otherwise sets {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the matching
19	 * owner's id (the lowest-id match when several qualify, so the value is deterministic); otherwise
20	 * {@code possibleDuplicate} is set false and {@code possibleDuplicateOf} left null. Hard duplicates —
21	 * an exact identity-key match — never reach here: they are rejected earlier by
22	 * {@link EnsureOwnerIdentityUnique}.
23	 *
24	 * <p>Runs after {@link NormalizeOwnerTelephone}/{@link NormalizeOwnerEmail} (so the identity key
25	 * compares in canonical form) and after {@link BuildOwner} (so the entity, its last name and postcode
26	 * exist), and before {@link SaveOwner} so the flag is persisted with the new row and read back by
27	 * {@code GET /api/owners/{id}}.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            owner.setPossibleDuplicate(false);
34	            owner.setPossibleDuplicateOf(null);
35	            return; // a declared household member is not a suspected duplicate
36	        }
37	        String surname = Soundex.encode(owner.getLastName());
38	        String postcode = owner.getPostcode();
39	        String identityKey = owner.getIdentityKey();
40	
41	        Integer matchId = null;
42	        if (postcode != null && !postcode.isBlank()) {
43	            for (Owner existing : ownerRepository.findAll()) {
44	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
45	                    continue;
46	                }
47	                if (Boolean.TRUE.equals(existing.getDeleted())) {
48	                    continue; // a soft-deleted owner is treated as absent
49	                }
50	                if (identityKey.equals(existing.getIdentityKey())) {
51	                    continue; // an exact identity match is a hard duplicate, not a soft one
52	                }
53	                if (surname.equals(Soundex.encode(existing.getLastName()))
54	                        && postcode.equals(existing.getPostcode())) {
55	                    if (matchId == null || existing.getId() < matchId) {
56	                        matchId = existing.getId();
57	                    }
58	                }
59	            }
60	        }
61	
62	        owner.setPossibleDuplicate(matchId != null);
63	        owner.setPossibleDuplicateOf(matchId);
64	    }
65	}
