3	/**
4	 * Minimal, dependency-free implementation of the classic American Soundex phonetic code: a surname is
5	 * reduced to its first letter followed by three digits, so that names which sound alike map to the same
6	 * code (e.g. {@code Robert}/{@code Rupert} both encode to {@code R163}).
7	 *
8	 * <p>Used to build an owner's {@code identityKey} (see {@link Owner#getIdentityKey()}) and to detect a
9	 * soft-match household duplicate, both of which key off how a surname <em>sounds</em> rather than its
10	 * exact spelling. Non-letters are ignored; a value with no letters encodes to the empty string.
11	 */
12	public final class Soundex {
13	
14	    private Soundex() {
15	    }
16	
17	    /** Encode {@code value} to its four-character Soundex code, or {@code ""} when it has no letters. */
18	    public static String encode(String value) {
19	        if (value == null) {
20	            return "";
21	        }
22	        StringBuilder letters = new StringBuilder();
23	        for (int i = 0; i < value.length(); i++) {
24	            char c = value.charAt(i);
25	            if (Character.isLetter(c)) {
26	                letters.append(Character.toUpperCase(c));
27	            }
28	        }
29	        if (letters.length() == 0) {
30	            return "";
31	        }
32	        StringBuilder code = new StringBuilder();
33	        code.append(letters.charAt(0));
34	        char prevDigit = digit(letters.charAt(0));
35	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
36	            char c = letters.charAt(i);
37	            // 'H' and 'W' are transparent: a same-coded letter on either side is still collapsed.
38	            if (c == 'H' || c == 'W') {
39	                continue;
40	            }
41	            char d = digit(c);
42	            if (d != '0' && d != prevDigit) {
43	                code.append(d);
44	            }
45	            // Vowels (digit '0') reset the run, so a repeat of a code across a vowel is emitted twice.
46	            prevDigit = d;
47	        }
48	        while (code.length() < 4) {
49	            code.append('0');
50	        }
51	        return code.toString();
52	    }
53	
54	    private static char digit(char c) {
55	        switch (c) {
56	            case 'B': case 'F': case 'P': case 'V':
57	                return '1';
58	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
59	                return '2';
60	            case 'D': case 'T':
61	                return '3';
62	            case 'L':
63	                return '4';
64	            case 'M': case 'N':
65	                return '5';
66	            case 'R':
67	                return '6';
68	            default:
69	                return '0';
70	        }
71	    }
72	}
