14	/**
15	 * Assigns the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the
16	 * region code derived from the owner's postcode (preferred), falling back to the city and then to
17	 * {@code UNKNOWN}, and HASH8 is the first eight UPPER-case hex characters of SHA-256 over
18	 * {@code normalizedTelephone + lastName} (e.g. 'NSW-1A2B3C4D').
19	 *
20	 * <p>The base code is a pure function of the region and hash, so two distinct owners can in principle
21	 * derive the same code. When the computed code collides with an existing owner's {@code customerCode},
22	 * this step de-duplicates it by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
23	 * makes it unique (e.g. 'NSW-1A2B3C4D-2', then 'NSW-1A2B3C4D-3'), so every persisted owner keeps a
24	 * distinct code.
25	 *
26	 * <p>Runs after {@link BuildOwner} and {@link NormalizeOwnerTelephone} (so the telephone is already
27	 * in canonical E.164 form) and before {@link SaveOwner}, mutating the not-yet-persisted owner in
28	 * place.
29	 */
30	public class AssignCustomerCode {
31	
32	    /** Fixed city-to-region table, mirroring the read-time locality derivation. */
33	    private static final Map<String, String> CITY_REGION = Map.of(
34	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
35	
36	    /** Region to its inclusive 4-digit postcode range {low, high}. */
37	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
38	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
39	
40	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
41	        String base = region(owner) + "-" + hash8(owner);
42	        owner.setCustomerCode(deduplicate(base, owner, ownerRepository));
43	    }
44	
45	    /**
46	     * Returns {@code base} when no existing owner already uses it, otherwise the first of
47	     * {@code base-2, base-3, ...} that is free — so distinct owners keep distinct codes.
48	     */
49	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
50	        Set<String> taken = new HashSet<>();
51	        for (Owner existing : ownerRepository.findAll()) {
52	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
53	                continue;
54	            }
55	            String code = existing.getCustomerCode();
56	            if (code != null) {
57	                taken.add(code);
58	            }
59	        }
60	        if (!taken.contains(base)) {
61	            return base;
62	        }
63	        for (int n = 2; ; n++) {
64	            String candidate = base + "-" + n;
65	            if (!taken.contains(candidate)) {
66	                return candidate;
67	            }
68	        }
69	    }
70	
71	    /** Region derived from the postcode when it falls in a known range, else the city, else UNKNOWN. */
72	    private static String region(Owner owner) {
73	        String byPostcode = regionFromPostcode(owner.getPostcode());
74	        if (byPostcode != null) {
75	            return byPostcode;
76	        }
77	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
78	    }
79	
80	    private static String regionFromPostcode(String postcode) {
81	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
82	            return null;
83	        }
84	        int value = Integer.parseInt(postcode);
85	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
86	            int[] range = entry.getValue();
87	            if (value >= range[0] && value <= range[1]) {
88	                return entry.getKey();
89	            }
90	        }
91	        return null;
92	    }
93	
94	    /** First eight UPPER-case hex characters of SHA-256 over (normalized telephone + last name). */
95	    private static String hash8(Owner owner) {
96	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
97	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
98	        byte[] digest;
99	        try {
100	            digest = MessageDigest.getInstance("SHA-256")
101	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
102	        }
103	        catch (NoSuchAlgorithmException ex) {
104	            throw new IllegalStateException("SHA-256 unavailable", ex);
105	        }
106	        StringBuilder sb = new StringBuilder(8);
107	        for (int i = 0; i < 4; i++) {
108	            sb.append(String.format("%02X", digest[i]));
109	        }
110	        return sb.toString();
111	    }
112	}
