315	
316	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
317	
318	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
319	        OwnerPageDto ownerPageDto = new OwnerPageDto();
320	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
321	        ownerPageDto.setPage(ownerPage.getNumber());
322	        ownerPageDto.setSize(ownerPage.getSize());
323	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
324	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
325	        return ownerPageDto;
326	    }
327	}
