     * separated by a single space (e.g. 'DR Franklin'), or just the last name when no
     * title was supplied (null or blank).
     */
    default String salutation(Owner owner) {
        if (owner == null) {
            return null;
        }
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
