package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;

import tools.jackson.databind.ObjectMapper;

/**
 * Emits an audit line to the dedicated {@code AUDIT} logger recording a successful owner
 * create. Runs after {@link SaveOwner} (so the owner id is assigned) and before the
 * responder. The line carries the owner id, the {@code memberId}, the
 * {@code registrationDate} and the {@code membershipLevel}.
 *
 * <p>Besides that human-readable line it emits an immutable structured {@link OwnerCreatedEvent}
 * as JSON to the same logger, with a {@code seq} that increases monotonically across creates.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final ObjectMapper MAPPER = new ObjectMapper();

    /** Monotonically increasing sequence across all owner creates. */
    private static final AtomicLong SEQ = new AtomicLong();

    public void service(@Val Owner owner) {
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                owner.getMembershipLevel(), owner.getMembershipNumber());

        // The owner's CURRENT primary identifier. Today that is the customerCode; when the
        // customerCode is later unified into the memberId, this one accessor changes and the
        // structured event automatically carries the memberId instead.
        String primaryIdentifier = owner.getCustomerCode();
        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
                primaryIdentifier, owner.getMembershipLevel(), OwnerCreatedEvent.OWNER_CREATED);
        AUDIT.info("{}", MAPPER.writeValueAsString(event));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Immutable structured audit event, emitted as JSON to the {@code AUDIT} logger alongside the
 * human-readable audit line whenever an owner is created.
 *
 * <p>Carries the owner id and the owner's <em>current primary identifier</em>. Today that primary
 * identifier is the {@code customerCode}; when the {@code customerCode} is later unified into the
 * {@code memberId}, the producer sources the identifier from that field instead and the event
 * automatically carries the {@code memberId}.
 *
 * <p>{@code seq} is a monotonically increasing integer across creates. Being a record, an event
 * cannot be mutated after construction.
 */
public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
        Integer membershipLevel, String event) {

    /** The single event type this record represents. */
    public static final String OWNER_CREATED = "OWNER_CREATED";
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.lang.reflect.Method;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.core.MethodParameter;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.validation.BeanPropertyBindingResult;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.MethodArgumentNotValidException;

/**
 * Resolves the EFFECTIVE registration date and rolls it onto a business day.
 *
 * <p>The effective date is the one supplied in the request, or the server's current date when the
 * request omits it. A supplied date later than the server's current date is rejected with 400 via
 * {@link MethodArgumentNotValidException} — an owner cannot be registered in the future. Otherwise,
 * when that date lands on a Saturday, Sunday or listed public holiday it is rolled forward to the
 * next non-holiday business day. The adjusted
 * date is published as a variable so every later step derives from the same value: the daily
 * create-limit counts owners per adjusted business day, {@link BuildOwner} stores it as the owner's
 * {@code registrationDate}, and {@link AssignMembershipNumber} takes the membership number's year
 * segment from it.
 *
 * <p>Runs before {@link EnsureDailyOwnerLimit} so the limit is checked against the adjusted date.
 */
public class NormalizeRegistrationDate {

    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    private static final Method SERVICE_METHOD;

    static {
        try {
            SERVICE_METHOD = NormalizeRegistrationDate.class.getMethod("service", OwnerFieldsDto.class, Out.class);
        }
        catch (NoSuchMethodException ex) {
            throw new ExceptionInInitializerError(ex);
        }
    }

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate)
            throws MethodArgumentNotValidException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
            binding.rejectValue("registrationDate", "FutureDate",
                "registration date must not be later than the current date");
            throw new MethodArgumentNotValidException(new MethodParameter(SERVICE_METHOD, 0), binding);
        }
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        registrationDate.set(toBusinessDay(effective));
    }

    private static LocalDate toBusinessDay(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
                || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }
}

